        UNION { VALUES ?root { wd:Q1421651 wd:Q1422324 wd:Q109324772 wd:Q2010006 wd:Q61000461 wd:Q7708427 wd:Q607699 wd:Q9358874 wd:Q4129836 wd:Q638123 wd:Q1888734 wd:Q1210082 wd:Q1118810 wd:Q3133388 wd:Q7851097 wd:Q7851772 wd:Q957589 wd:Q4489310 wd:Q232976 wd:Q10880330 } ?item wdt:P279 ?root }
        UNION { VALUES ?root { wd:Q1421651 wd:Q1422324 wd:Q109324772 wd:Q2010006 wd:Q61000461 wd:Q7708427 wd:Q607699 wd:Q9358874 wd:Q4129836 wd:Q638123 wd:Q1888734 wd:Q1210082 wd:Q1118810 wd:Q3133388 wd:Q7851097 wd:Q7851772 wd:Q957589 wd:Q4489310 wd:Q232976 wd:Q10880330 } BIND(?root AS ?item) }
